/**
 * A Button preset whose face is an Avatar (`design/components/avatar-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  agentMember,
  agentPress,
  claimSlot,
  createDerived,
  elementRef,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/avatar-button.module.css'
import Avatar from '../structure/Avatar'

export interface AvatarButtonProps {
  /**
   * Marks the button as the current location with `aria-current="page"`, as Button's `current`
   * does.
   */
  current?: boolean
  disabled?: boolean
  /**
   * The accessible name of the action, such as "Account menu". It is required and it is not the
   * person's name: a face says who, and a button says what a press does.
   */
  label: string
  /**
   * The action has started and not finished. Keeps focus and name, hides the face behind the
   * spinner, and ignores presses.
   */
  loading?: boolean
  /**
   * Avatar's `name`: the initials, and the `user` glyph when it is empty. Never the accessible
   * name.
   */
  name: string
  onClick?: (event: MouseEvent) => void
  /**
   * Makes the button a toggle, as Button's `pressed` does: `aria-pressed` mirrors it and
   * `data-state="on|off"` exposes it to CSS. Omitted, the button is not a toggle.
   */
  pressed?: boolean
  /**
   * The face's size, which is Avatar's. The box around it is never smaller than the size's
   * control height.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * Avatar's `src`: the image. A URL that fails to load leaves the initials.
   */
  src?: string
}

/** A Button preset whose face is an Avatar. */
export default function AvatarButton(given: AvatarButtonProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', disabled: false, loading: false, current: false } as Defaults<
      AvatarButtonProps,
      'size' | 'disabled' | 'loading' | 'current'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const control = elementRef<HTMLElement>()
    const dataState = createDerived(() =>
      props.loading
        ? 'loading'
        : props.pressed === undefined
          ? undefined
          : props.pressed
            ? 'on'
            : 'off',
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'AvatarButton',
        element: () => control.value,
        state: () => ({ disabled: props.disabled, loading: props.loading }),
        actions: { press: () => agentPress(control.value) },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <button
        class={styles.button}
        type="button"
        disabled={props.disabled}
        aria-label={props.label}
        aria-busy={props.loading ? true : undefined}
        aria-current={props.current ? 'page' : undefined}
        aria-pressed={props.pressed}
        data-variant="ghost"
        data-tone="neutral"
        data-size={props.size}
        data-state={dataState.value}
        data-disabled={props.disabled ? '' : undefined}
        data-member="avatar-button"
        onclick={($event: MouseEvent) => !props.loading && props.onClick?.($event)}
        ref={control.attach}
      >
        {/* face */}
        <span class={styles.face}>
          <Avatar name={props.name} src={props.src} size={props.size} />
        </span>
        {props.loading ? (
          <span class={styles.spinner}>
            <Icon name="loading" size={props.size} />
          </span>
        ) : null}
      </button>
    )
  })
}
